arguments.newString:
def _sanitize_value_amount(val: Optional[float], *, min_amount: float = 100_000) -> Optional[float]:
    if val is None:
        return None
    try:
        f = float(val)
    except (TypeError, ValueError):
        return None
    # ``min_amount`` is the smallest *accepted* value, not an exclusive floor:
    # an appraisal that concludes exactly at the floor is still a valid value.
    return f if f >= min_amount else None

